/* =====================================================================================================================
   [03/11/2026 - Alexandre Carvalho] GESTOR FINANCEIRO - BAIXAR E CONCILIAR (QUALITY): CHEQUE RECEBIDO DEVOLVIDO - CONFIGURACAO.
   O extrato traz a devolucao como TPD CHRD (debito), historico "DEV CH NAC|DEP <banco> <n. cheque> <alinea>" (14424, desde 23/10/2026).
   Fluxo decidido pelo Alexandre (03/11): casa a linha CHRD com o cheque de MEGA.CUS_FIN_CHEQUESCRE (banco + numero + valor), reabre os
   titulos baixados pelo cheque (exclui a baixa 706 - o trigger CCS_T_MOV_CHQ registra o estorno no cheque), marca o cheque D com a alinea,
   avisa a EQUIPE INTERNA por WhatsApp (fila CCS_TB_ZAP_MSG_ATIVO, lista de distribuicao) e lanca a acao 971 "Estorno Devolucao de Cheque recebido" (TPD CHRD) para conciliar o debito.
   Sem bloqueio do cliente. Diagnostico: agenda_02_11_a_08_11/mm45g41_01..17.
   Este arquivo so cria a configuracao (parametros BXC_CHD_* + coluna da conta). Tudo nasce DESLIGADO. SO ASCII. Blocos separados por "/".
   ===================================================================================================================== */
ALTER TABLE MEGA.CCS_TB_GFIN_BXC_CONTA ADD (CTA_CH_AUTO_CHD CHAR(1) DEFAULT 'N' NOT NULL CONSTRAINT CCS_CK_GFIN_BXC_CONTA_CHD CHECK (CTA_CH_AUTO_CHD IN ('S','N')))
/
MERGE INTO MEGA.CCS_TB_GFIN_PARAM D USING (
  SELECT 'BXC_CHD_ATIVO' CH, 0 VL, 'BXC CHEQUE DEVOLVIDO: ROBO LIGADO (1) / DESLIGADO (0)' DS FROM DUAL UNION ALL
  SELECT 'BXC_CHD_DESDE', 20261023, 'BXC CHEQUE DEVOLVIDO: SO TRATA LINHAS CHRD COM DATA >= AAAAMMDD (ANTERIORES FICAM COMO ESTAO - DECISAO 03/11/2026)' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_USU', 0, 'BXC CHEQUE DEVOLVIDO: USUARIO DO MEGA QUE GRAVA O ESTORNO E O LANCAMENTO 971' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_TETO', 10000, 'BXC CHEQUE DEVOLVIDO: VALOR MAXIMO POR CHEQUE PARA O ROBO (ACIMA VAI PARA A TELA)' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_JANELA', 90, 'BXC CHEQUE DEVOLVIDO: DEVOLUCAO ATE N DIAS DEPOIS DO BOM PARA DO CHEQUE' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_REABRE', 1, 'BXC CHEQUE DEVOLVIDO: REABRIR OS TITULOS BAIXADOS PELO CHEQUE (1/0)' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_MARCA', 1, 'BXC CHEQUE DEVOLVIDO: MARCAR O CHEQUE COMO DEVOLVIDO (D) COM A ALINEA (1/0)' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_WHATS', 0, 'BXC CHEQUE DEVOLVIDO: AVISAR A EQUIPE INTERNA POR WHATSAPP (FILA CCS_TB_ZAP_MSG_ATIVO, LINHA 1) (1/0)' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_ZAP_LISTA', 11, 'BXC CHEQUE DEVOLVIDO: LISTA DE DISTRIBUICAO DO WHATSAPP (CCS_TB_ZAP_DISTRIB; 11 = CONTAS A RECEBER/COBRANCA)' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_ACAO', 971, 'BXC CHEQUE DEVOLVIDO: ACAO DO MEGA DO LANCAMENTO QUE CONCILIA O DEBITO CHRD' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_CLASSE', 0, 'BXC CHEQUE DEVOLVIDO: CLASSE FINANCEIRA DO LANCAMENTO 971 (0 = A DEFINIR COM A CONTABILIDADE)' FROM DUAL UNION ALL
  SELECT 'BXC_CHD_CCUSTO', 0, 'BXC CHEQUE DEVOLVIDO: CENTRO DE CUSTO DO LANCAMENTO 971 (0 = A DEFINIR)' FROM DUAL
) S ON (D.PARAM_ST_CHAVE = S.CH)
WHEN MATCHED THEN UPDATE SET D.PARAM_ST_DESCRICAO = S.DS
WHEN NOT MATCHED THEN INSERT (PARAM_ST_CHAVE, PARAM_RE_VALOR, PARAM_ST_DESCRICAO) VALUES (S.CH, S.VL, S.DS)
/
